<script setup>import { Head,Link,useForm } from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({category:Object}); const editing=!!props.category; const form=useForm({name:props.category?.name||'',description:props.category?.description||'',is_active:props.category?.is_active??true,sort_order:props.category?.sort_order??0}); const submit=()=>editing?form.put(`/admin/categories/${props.category.id}`):form.post('/admin/categories');</script>
<template><AppLayout><Head :title="editing?'ویرایش دسته‌بندی':'دسته‌بندی جدید'"/><section class="rounded-2xl border bg-white p-6"><h1 class="mb-6 text-xl font-bold">{{ editing?'ویرایش دسته‌بندی':'ایجاد دسته‌بندی' }}</h1><form class="space-y-4" @submit.prevent="submit"><div><label>نام</label><input v-model="form.name"><p class="text-sm text-red-600">{{ form.errors.name }}</p></div><div><label>توضیحات</label><textarea v-model="form.description" rows="4" class="w-full rounded-xl border p-3"></textarea></div><div><label>ترتیب نمایش</label><input v-model.number="form.sort_order" type="number" min="0"></div><label class="flex items-center gap-2"><input v-model="form.is_active" type="checkbox" class="h-4 w-4"> فعال</label><div class="flex gap-3"><button class="rounded-xl bg-teal-700 px-5 py-2.5 font-bold text-white">ذخیره</button><Link href="/admin/categories" class="rounded-xl border px-5 py-2.5">انصراف</Link></div></form></section></AppLayout></template>
